#!/bin/bash
# Builds the C toolchain that runs ON the Mac (GCC 1.42 cpp + cc1, as, ld, cc and libraries)
# and installs it into user/rootdir. Called by user/build.sh.
#
# Generated by LLM
#
#   /usr/bin/{cc,cpp,cc1,as,ld}
#   /usr/lib/{crt0.o,libc.a,libm.a,libgcc1.a,libgcc.a}
#   /usr/lib/gcc/include/{stdarg.h,varargs.h,stddef.h}   /usr/lib/gcc/tests
#   /usr/include

set -e

cd "$(dirname "$0")"

CC_DIR="$(pwd)"
UCLINUX_DIR="$(cd ../../uClinux && pwd)"
GCC_DIR="$(cd ../../gcc && pwd)"
ROOTDIR="${ROOTDIR:-$(cd .. && pwd)/rootdir}"

if [ ! -f "${GCC_DIR}/cccp.c" ]; then
    echo "GCC 1.42 source is missing from ${GCC_DIR}" >&2
    exit 1
fi

echo " ==== building the on-Mac C toolchain..."
docker run \
    --user $(id -u):$(id -u) \
    --mount type=bind,source="${CC_DIR}",target=/build${CTR_MOUNT_OPTS} \
    --mount type=bind,source="${UCLINUX_DIR}",target=/linux${CTR_MOUNT_OPTS} \
    --mount type=bind,source="${GCC_DIR}",target=/gcc,readonly${CTR_MOUNT_OPTS} \
    --workdir /build \
    -t uclinux-buildenv:0.1 \
    sh /build/build-in-container.sh

echo " ==== installing the toolchain into ${ROOTDIR}"
mkdir -p "${ROOTDIR}/usr/bin" "${ROOTDIR}/usr/lib/gcc/include" "${ROOTDIR}/usr/include"
for t in cc cc1 cpp as ld; do
    cp --remove-destination "build/bin/$t" "${ROOTDIR}/usr/bin/$t"
done
for l in crt0.o libc.a libm.a libgcc1.a libgcc.a; do
    cp --remove-destination "build/lib/$l" "${ROOTDIR}/usr/lib/$l"
done

# headers: the libc ones (asm, linux and machine are symlinks, copy what they point to)
rm -rf "${ROOTDIR}/usr/include" "${ROOTDIR}/usr/lib/gcc/include" "${ROOTDIR}/usr/lib/gcc/tests"
mkdir -p "${ROOTDIR}/usr/include" "${ROOTDIR}/usr/lib/gcc/include" "${ROOTDIR}/usr/lib/gcc/tests"
cp -rL "${UCLINUX_DIR}/lib/libc/include/." "${ROOTDIR}/usr/include/"
rm -rf "${ROOTDIR}/usr/include/arm" "${ROOTDIR}/usr/include/or32" "${ROOTDIR}/usr/include/sparc"
# GCC 1.42 only knows plain identifiers inside __attribute__ (( ))
cat gcc-features-shim.h >> "${ROOTDIR}/usr/include/features.h"
# GCC's own headers (stdarg.h and varargs.h are named gstdarg.h, gvarargs.h in the source)
cp "${GCC_DIR}/gstdarg.h" "${ROOTDIR}/usr/lib/gcc/include/stdarg.h"
cp "${GCC_DIR}/gvarargs.h" "${ROOTDIR}/usr/lib/gcc/include/varargs.h"
cp "${GCC_DIR}/stddef.h" "${ROOTDIR}/usr/lib/gcc/include/stddef.h"
# the on-Mac tests: sh /usr/lib/gcc/tests/run.sh
cp tests/*.c tests/*.expected tests/run.sh "${ROOTDIR}/usr/lib/gcc/tests/"

chmod 755 "${ROOTDIR}"/usr/bin/{cc,cc1,cpp,as,ld}
